def mk(p,w,mode):
    C=np.cos(w*t);S=np.sin(w*t);vp=v**p
    if mode==0: return np.column_stack([np.ones_like(t),C,S,vp])
    if mode==1: return np.column_stack([np.ones_like(t),C,S,vp,v*C,v*S])
    if mode==2: return np.column_stack([np.ones_like(t),C,S,v,v*np.abs(v),vp*C,vp*S])
    if mode==3: return np.column_stack([np.ones_like(t),C,S,v,vp,x])
def loss(q,mode):
    A=mk(q[1],q[0],mode); c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
    return np.sum((A@c-dv_dt)**2)/ss
